"""External-logic hook for the date dimension, generated by LakeLogic Build Studio.

Delegates to LakeLogic core's calendar generator. Its frame replaces the header-only seed rows
before the contract validates them, so the contract's model names exactly these columns.
"""
from __future__ import annotations

from lakelogic.core.dim_date import generate_date_dimension


def run(good_df=None, **kwargs):
    frame = generate_date_dimension(
        start_date=kwargs.get("start_date", "2020-01-01"),
        end_date=kwargs.get("end_date", "2030-12-31"),
        fiscal_year_start_month=int(kwargs.get("fiscal_year_start_month", 1)),
        engine="polars",
    )
    # The frame type the step runs on: a Spark step is handed a Spark frame and gets one back.
    spark = getattr(good_df, "sparkSession", None) if good_df is not None else None
    if spark is not None:
        return spark.createDataFrame(frame.to_pandas())
    return frame
